import { createHash } from 'node:crypto';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';

const hash = value => createHash('sha256').update(value).digest('hex');
const noop = () => {};
/** Captured before the V2 implementation; the expected file is never regenerated by tests. */
export async function captureV1(vite) {
  const { articleContents } = await vite.ssrLoadModule('/app/data.ts');
  const { StudySentence, QuestionStudyCard } = await vite.ssrLoadModule('/app/study-app.tsx');
  const { OriginalPassage } = await vite.ssrLoadModule('/app/original-passage.tsx');
  return Object.fromEntries(Object.values(articleContents).filter(a => a.experienceVersion !== 2).map(article => {
    const html = [renderToStaticMarkup(React.createElement(OriginalPassage, { article, marked: new Set(), onMark: noop }))];
    for (const sentence of article.sentences) for (const mode of ['read', 'words', 'structure']) for (const isExpanded of [false, true]) {
      html.push(renderToStaticMarkup(React.createElement(StudySentence, { sentence, mode, isExpanded, isMarked: false, note: '', onToggle: noop, onMark: noop, onTerm: noop, onNote: noop })));
    }
    for (const question of article.questions) html.push(renderToStaticMarkup(React.createElement(QuestionStudyCard, { question, onTerm: noop, onSentence: noop })));
    return [article.id, { content: hash(JSON.stringify(article)), render: hash(html.join('\n')), sentences: article.sentences.length, questions: article.questions.length }];
  }));
}
